(* ZSTD_emptyBuffer (fix F9), the base ZSTD_decompressStream and ZSTD_decompressMultiFrame take for an empty buffer
   passed as NULL: a readable byte, never read.  The share is any readable one, so that these functions can lend a
   part of it as the pointer witness of their empty base and keep zstd_globals for their callees. *)
Definition eb_res (gv: globals) : mpred :=
  EX sh: share, !! readable_share sh && data_at sh (tarray tuchar 1) [Vint (Int.repr 0)] (gv _ZSTD_emptyBuffer).

Definition zstd_globals (gv: globals) : mpred := (
  data_at Ews tint g_debuglevel_val (gv _g_debuglevel) *
  data_at Ers (tarray tuint 32) DeBruijnBytePos_val (gv _DeBruijnBytePos) *
